.cookie-consent {
  position: fixed;
  right: clamp(16px, 3vw, 36px);
  bottom: clamp(16px, 3vw, 36px);
  z-index: 1300;
  width: min(570px, calc(100vw - 32px));
  padding: 18px;
  display: grid;
  grid-template-columns: 68px minmax(0, 1fr);
  gap: 10px 16px;
  align-items: center;
  color: #f8f7ff;
  border: 1px solid rgba(196, 181, 253, 0.24);
  border-radius: 22px;
  background: linear-gradient(145deg, rgba(15, 10, 31, 0.97), rgba(49, 46, 129, 0.96));
  box-shadow: 0 24px 70px rgba(15, 10, 31, 0.42);
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 0.25s ease, transform 0.25s ease;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.cookie-consent.is-visible {
  opacity: 1;
  transform: translateY(0);
}

.cookie-consent-icon {
  width: 68px;
  height: 68px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(196, 181, 253, 0.2);
  border-radius: 20px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.1), rgba(124, 58, 237, 0.1));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.11);
}

.cookie-consent-icon svg {
  width: 62px;
  height: 62px;
  overflow: visible;
}

.cookie-consent h2 {
  margin: 0 0 6px;
  color: #fff;
  font-family: 'Montserrat', sans-serif;
  font-size: 1.05rem;
  line-height: 1.3;
}

.cookie-consent p {
  margin: 0;
  color: rgba(248, 247, 255, 0.76);
  font-size: 0.86rem;
  line-height: 1.55;
}

.cookie-consent-actions {
  grid-column: 2;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.cookie-consent button {
  min-height: 44px;
  padding: 10px 16px;
  border-radius: 13px;
  font: 700 0.84rem 'Inter', sans-serif;
  cursor: pointer;
}

.cookie-consent-accept {
  color: #fff;
  border: 1px solid transparent;
  background: linear-gradient(135deg, #6d28d9, #8b5cf6);
  box-shadow: 0 10px 24px rgba(124, 58, 237, 0.28);
}

.cookie-consent-reject {
  color: #ddd6fe;
  border: 1px solid rgba(221, 214, 254, 0.22);
  background: rgba(255, 255, 255, 0.06);
}

.cookie-settings-button {
  padding: 0;
  color: inherit;
  border: 0;
  background: none;
  font: inherit;
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}

@media (max-width: 640px) {
  .cookie-consent {
    left: 12px;
    right: 12px;
    bottom: calc(12px + env(safe-area-inset-bottom));
    width: auto;
    padding: 18px;
    grid-template-columns: 58px minmax(0, 1fr);
    gap: 10px 14px;
  }

  .cookie-consent-icon {
    width: 58px;
    height: 58px;
    border-radius: 17px;
  }

  .cookie-consent-icon svg {
    width: 54px;
    height: 54px;
  }

  .cookie-consent-actions {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .cookie-consent button {
    font-size: 0.8rem;
  }
}

@media (max-width: 390px) {
  .cookie-consent-actions {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cookie-consent {
    transition: none;
  }
}


