.chat-header-status{font-size:.76rem}
.chat-header-status::before{width:7px;height:7px}
.chat-header-buttons{gap:.4rem}
.chat-expand,.chat-close{width:31px;height:31px}
.chat-expand img,.chat-close img{width:17px;height:17px}
.chat-widget-icon{display:flex;align-items:center;justify-content:center}
.chat-widget-icon img{width:31px;height:31px}
.chat-message-avatar img{width:21px;height:21px}
.chat-send img{width:22px;height:22px}
.chat-quick-label{margin:0;padding:.72rem 1.5rem .12rem;background:#fff;color:#475569;font-size:.78rem;font-weight:600;line-height:1.3}
.chat-quick-label::before{display:inline-block;width:7px;height:7px;margin-right:.45rem;background:var(--primary);border-radius:50%;content:"";animation:quick-label-pulse 1.5s ease-in-out infinite}
.chat-quick-label[hidden]{display:none}
.chat-quick-actions{max-height:116px;padding:.55rem 1.5rem .75rem;overflow-y:auto}
.chat-quick-btn{border:1px solid rgba(124,58,237,.16);font-weight:600}
.chat-quick-actions.is-fresh .chat-quick-btn{animation:quick-option-in .5s cubic-bezier(.2,.8,.2,1) both}
.chat-quick-actions.is-fresh .chat-quick-btn:nth-child(2){animation-delay:.05s}
.chat-quick-actions.is-fresh .chat-quick-btn:nth-child(3){animation-delay:.1s}
.chat-quick-actions.is-fresh .chat-quick-btn:nth-child(4){animation-delay:.15s}
@keyframes quick-option-in{0%{opacity:.45;transform:translateY(7px)}100%{opacity:1;transform:translateY(0)}}
@keyframes quick-label-pulse{0%,100%{box-shadow:0 0 0 0 rgba(124,58,237,.35)}50%{box-shadow:0 0 0 5px rgba(124,58,237,0)}}
.chat-privacy-note{margin:0;padding:.2rem 1.5rem .7rem;background:#fff;color:#94a3b8;font-size:.72rem;line-height:1.35}
.chat-messenger-actions{display:grid;gap:.55rem;margin-top:.85rem}
.chat-telegram-link,.chat-vk-link{display:flex;align-items:center;justify-content:center;padding:.75rem 1rem;border-radius:14px;color:#fff!important;text-align:center;text-decoration:none;font-size:.84rem;line-height:1.25;transition:transform .2s,box-shadow .2s}
.chat-telegram-link{background:var(--gradient-1)}
.chat-vk-link{background:linear-gradient(135deg,#2787f5 0%,#07f 100%)}
.chat-telegram-link:hover{box-shadow:0 8px 24px rgba(124,58,237,.3);transform:translateY(-1px)}
.chat-vk-link:hover{box-shadow:0 8px 24px rgba(39,135,245,.3);transform:translateY(-1px)}
.chat-draft-note{display:block;margin-top:.55rem;color:#64748b;font-size:.72rem;line-height:1.35}
.chat-input{min-width:0}
@media (max-width:768px){
  .chat-quick-actions{max-height:132px}
  .chat-privacy-note{padding-bottom:.55rem}
  .chat-input{font-size:16px}
  .chat-window.active{height:100dvh;max-height:100dvh}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}
}

.error-page{min-height:100vh;display:grid;place-items:center;padding:2rem;background:var(--gradient-2);color:#fff;text-align:center}
.error-page main{max-width:680px}
.error-code{font-size:clamp(6rem,22vw,13rem);font-weight:900;line-height:.85;background:var(--gradient-1);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}
.error-page h1{margin:2rem 0 1rem;font-size:clamp(2rem,6vw,3.5rem)}
.error-page p{margin-bottom:2rem;color:rgba(255,255,255,.72);font-size:1.1rem}

/* Утверждённая шрифтовая система: Montserrat для акцентов, Inter для чтения. */
:root{
  --font-body:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
  --font-display:'Montserrat','Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
}
body{font-family:var(--font-body)}
.preloader-logo,
.preloader-percentage,
.logo,
.footer-logo,
.hero-text h1,
.section-header h2,
.service-title,
.why-title,
.process-step h3,
.result-title,
.pricing-name,
.faq-question h3,
.cta-content h2,
.online-consultant h3,
.footer-column h4,
.floating-card-content h4,
.error-page h1,
.error-code,
.hero-stat-number,
.service-number,
.process-step-number,
.result-metric,
.pricing-price,
.section-badge,
.btn,
.nav-cta,
.pricing-btn,
.messenger-btn,
.consultant-btn{font-family:var(--font-display)}
.hero-text h1{font-weight:800}
.section-header h2,
.cta-content h2{font-weight:800}
.service-title,
.why-title,
.process-step h3,
.result-title,
.pricing-name,
.online-consultant h3,
.footer-column h4,
.floating-card-content h4,
.faq-question h3{font-weight:700}
.btn,
.nav-cta,
.section-badge{font-weight:600}
.pricing-btn,
.messenger-btn,
.consultant-btn{font-weight:700}
.chat-window,
.chat-window button,
.chat-window input{font-family:var(--font-body)}

/* Бесшовная бегущая строка с равномерными разделителями. */
.marquee{
  display:flex;
  align-items:center;
  width:max-content;
  animation:none;
  will-change:transform;
}
.marquee.is-ready{
  animation:marquee-seamless var(--marquee-duration,50s) linear infinite;
}
.marquee-content{
  display:flex;
  align-items:center;
  flex-shrink:0;
  gap:0;
  padding:0;
}
.marquee-item{
  display:inline-flex;
  align-items:center;
  flex-shrink:0;
  gap:0;
  white-space:nowrap;
}
.marquee-item::after{
  content:'★';
  flex-shrink:0;
  margin-inline:2rem;
  color:var(--primary);
  font-size:.9em;
  line-height:1;
}
@keyframes marquee-seamless{
  from{transform:translate3d(0,0,0)}
  to{transform:translate3d(var(--marquee-shift),0,0)}
}
@media(max-width:768px){
  .marquee-item::after{margin-inline:1.4rem}
}
@media(max-width:480px){
  .marquee-item::after{margin-inline:1.1rem}
}
@media(prefers-reduced-motion:reduce){
  .marquee.is-ready{animation:none;transform:none}
}

/* Объемные PNG-иконки для карточек услуг. */
.service-icon{
  width:92px;
  height:92px;
  overflow:visible;
  border:1px solid rgba(124,58,237,.1);
  border-radius:28px;
  background:radial-gradient(circle at 35% 25%,rgba(255,255,255,.94),rgba(124,58,237,.1));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.8),0 12px 30px rgba(76,29,149,.1);
}
.service-icon img{
  width:88px;
  height:88px;
  object-fit:contain;
  transform:scale(.96);
  filter:drop-shadow(0 8px 12px rgba(76,29,149,.16));
  transition:transform .5s cubic-bezier(.4,0,.2,1),filter .5s;
}
.service-card:hover .service-icon{
  border-color:rgba(255,255,255,.28);
  background:rgba(255,255,255,.16);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.25),0 14px 34px rgba(15,10,31,.18);
}
.service-card:hover .service-icon img{
  transform:scale(1.08) rotate(-3deg) translateY(-2px);
  filter:drop-shadow(0 12px 16px rgba(15,10,31,.24));
}
.service-card:nth-child(even):hover .service-icon img{
  transform:scale(1.08) rotate(3deg) translateY(-2px);
}

/* Объемные иконки и аккуратный hover в блоке подхода. */
.why-card{
  display:flex;
  flex-direction:column;
  align-items:center;
  min-height:370px;
}
.why-icon{
  width:108px;
  height:108px;
  overflow:visible;
  border:1px solid rgba(255,255,255,.12);
  border-radius:30px;
  background:radial-gradient(circle at 35% 25%,rgba(255,255,255,.15),rgba(124,58,237,.16));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.12),0 18px 40px rgba(5,2,14,.25);
}
.why-icon img{
  width:104px;
  height:104px;
  object-fit:contain;
  transform:scale(.96);
  filter:drop-shadow(0 10px 14px rgba(5,2,14,.28));
  transition:transform .5s cubic-bezier(.4,0,.2,1),filter .5s;
}
.why-title{
  display:flex;
  align-items:center;
  justify-content:center;
  min-height:3.25rem;
}
.why-card:hover{
  box-shadow:0 26px 65px rgba(5,2,14,.3),0 0 45px rgba(124,58,237,.16);
}
.why-card:hover .why-icon{
  border-color:rgba(167,139,250,.45);
  background:radial-gradient(circle at 35% 25%,rgba(255,255,255,.23),rgba(124,58,237,.3));
}
.why-card:hover .why-icon img{
  transform:scale(1.08) rotate(-3deg) translateY(-3px);
  filter:drop-shadow(0 15px 19px rgba(5,2,14,.38));
}
.why-card:nth-child(even):hover .why-icon img{
  transform:scale(1.08) rotate(3deg) translateY(-3px);
}

/* Световой пучок и темные стеклянные плашки в процессе работы. */
.process-timeline::before{
  top:55px;
  height:3px;
  background:linear-gradient(90deg,rgba(124,58,237,.16),rgba(124,58,237,.62) 18%,rgba(167,139,250,.78) 50%,rgba(124,58,237,.62) 82%,rgba(124,58,237,.16));
  box-shadow:0 0 16px rgba(124,58,237,.22);
}
.process-timeline::after{
  position:absolute;
  top:53px;
  left:-6%;
  z-index:1;
  width:16%;
  height:7px;
  border-radius:7px;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.98),transparent);
  box-shadow:0 0 14px rgba(255,255,255,.5),0 0 30px rgba(167,139,250,.42);
  filter:blur(1px);
  content:'';
  animation:process-light 10s linear infinite;
}
@keyframes process-light{
  0%{transform:translateX(0);opacity:0}
  4%{opacity:1}
  96%{opacity:1}
  100%{transform:translateX(600%);opacity:0}
}
.process-steps{z-index:2}
.process-step-number{
  width:110px;
  height:110px;
  border:1px solid rgba(255,255,255,.11);
  border-radius:32px;
  background:linear-gradient(145deg,rgba(20,13,38,.97) 0%,rgba(31,20,56,.94) 52%,rgba(54,30,88,.92) 100%);
  -webkit-backdrop-filter:blur(20px) saturate(135%);
  backdrop-filter:blur(20px) saturate(135%);
  color:#fff;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.13),inset 0 -20px 34px rgba(124,58,237,.08),0 18px 38px rgba(15,10,31,.22),0 0 0 rgba(124,58,237,0);
  font-size:2.25rem;
  text-shadow:0 2px 14px rgba(124,58,237,.75);
  transform:rotate(-3deg);
  z-index:2;
  animation:process-node-light 10s linear infinite;
  transition:transform .45s cubic-bezier(.4,0,.2,1),background .45s,border-color .45s;
}
.process-step-number::before{
  position:absolute;
  inset:7px;
  border-top:1px solid rgba(255,255,255,.14);
  border-left:1px solid rgba(255,255,255,.08);
  border-radius:25px;
  background:linear-gradient(135deg,rgba(255,255,255,.08),rgba(255,255,255,.015) 44%,transparent 45%);
  content:'';
}
.process-step:nth-child(1) .process-step-number{animation-delay:0s}
.process-step:nth-child(2) .process-step-number{animation-delay:2.4s;transform:rotate(3deg)}
.process-step:nth-child(3) .process-step-number{animation-delay:5s}
.process-step:nth-child(4) .process-step-number{animation-delay:7.6s;transform:rotate(3deg)}
@keyframes process-node-light{
  0%,25%,100%{
    border-color:rgba(255,255,255,.11);
    box-shadow:inset 0 1px 0 rgba(255,255,255,.13),inset 0 -20px 34px rgba(124,58,237,.08),0 18px 38px rgba(15,10,31,.22),0 0 0 rgba(124,58,237,0);
  }
  5%,20%{
    border-color:rgba(167,139,250,.28);
    box-shadow:inset 0 1px 0 rgba(255,255,255,.22),inset 0 -22px 36px rgba(124,58,237,.12),0 20px 42px rgba(76,29,149,.25),0 0 24px rgba(124,58,237,.2),0 16px 42px rgba(124,58,237,.22);
  }
  12%{
    border-color:rgba(196,181,253,.58);
    box-shadow:inset 0 1px 0 rgba(255,255,255,.38),inset 0 -24px 40px rgba(124,58,237,.18),0 22px 46px rgba(76,29,149,.3),0 0 34px rgba(167,139,250,.36),0 18px 58px rgba(124,58,237,.42);
  }
}
.process-step:hover .process-step-number{
  background:linear-gradient(145deg,rgba(27,17,49,.98) 0%,rgba(47,27,79,.95) 52%,rgba(76,39,122,.92) 100%);
  transform:translateY(-7px) scale(1.06) rotate(3deg);
}
.process-step:nth-child(even):hover .process-step-number{
  transform:translateY(-7px) scale(1.06) rotate(-3deg);
}
.process-step h3{
  min-height:3.2rem;
  display:flex;
  align-items:center;
  justify-content:center;
}
.process-step p{
  max-width:250px;
  color:#64748b;
}

/* Стабильная отрисовка текста во время 3D-поворота. */
@media(hover:hover) and (pointer:fine){
  .service-card{
    backface-visibility:hidden;
    will-change:transform;
  }
  .service-card .service-content,
  .service-card .service-visual{
    backface-visibility:hidden;
  }
  .service-card.animate-on-scroll{transform:translate3d(0,30px,0)}
  .service-card.animate-on-scroll.visible{transform:translate3d(0,0,0)}
  .service-card.animate-on-scroll.visible:hover{
    transform:translate3d(0,-10px,0) rotateX(5deg) rotateY(-5deg);
  }
}

@media(max-width:768px){
  .service-icon{width:84px;height:84px;border-radius:25px}
  .service-icon img{width:80px;height:80px}
  .why-card{min-height:0}
  .why-icon{width:98px;height:98px;border-radius:27px}
  .why-icon img{width:94px;height:94px}
  .why-title{min-height:0}
}

@media(max-width:992px){
  .process-timeline::after{display:none}
  .process-step-number{animation:none}
  .process-step h3{min-height:0}
}

@media(prefers-reduced-motion:reduce){
  .process-timeline::after{animation:none;opacity:0}
  .process-step-number{animation:none}
}

/* Честный блок результата без неподтвержденных числовых обещаний. */
.results-section{
  background:linear-gradient(180deg,#fff 0%,#faf8ff 100%);
  overflow:hidden;
}
.results-grid{
  gap:2rem;
}
.result-card{
  min-height:330px;
  padding:3rem;
  isolation:isolate;
  justify-content:flex-end;
  border:1px solid rgba(255,255,255,.18);
  box-shadow:0 24px 60px rgba(76,29,149,.18);
}
.result-card::before{
  top:-150px;
  right:-100px;
  z-index:-2;
  width:360px;
  height:360px;
  background:radial-gradient(circle,rgba(255,255,255,.18) 0%,rgba(255,255,255,.04) 54%,transparent 72%);
}
.result-card::after{
  position:absolute;
  inset:auto -15% -55% 20%;
  z-index:-2;
  height:85%;
  border-radius:50%;
  background:radial-gradient(circle,rgba(196,181,253,.22),transparent 68%);
  content:'';
  transition:transform .6s cubic-bezier(.4,0,.2,1),opacity .6s;
}
.result-card-1{background:linear-gradient(135deg,#4c1d95 0%,#6d28d9 54%,#7c3aed 100%)}
.result-card-2{background:linear-gradient(135deg,#312e81 0%,#5b21b6 52%,#8b5cf6 100%)}
.result-card-3{background:linear-gradient(135deg,#3b1774 0%,#6d28d9 52%,#7c3aed 100%)}
.result-card-4{background:linear-gradient(135deg,#241047 0%,#4c1d95 50%,#7c3aed 100%)}
.result-icon{
  position:absolute;
  top:1.15rem;
  right:1.35rem;
  z-index:-1;
  width:175px;
  height:175px;
  margin:0;
  opacity:.96;
  pointer-events:none;
}
.result-icon img{
  width:100%;
  height:100%;
  object-fit:contain;
  filter:drop-shadow(0 18px 24px rgba(15,10,31,.28));
  transform:rotate(2deg);
  transition:transform .6s cubic-bezier(.4,0,.2,1),filter .6s;
}
.result-category{
  position:absolute;
  top:2.35rem;
  left:3rem;
  max-width:calc(100% - 220px);
  font-size:.78rem;
  font-weight:700;
  letter-spacing:1.8px;
}
.result-title{
  max-width:72%;
  margin-bottom:.9rem;
  font-size:1.75rem;
  line-height:1.25;
}
.result-note{
  align-self:flex-start;
  margin-bottom:.85rem;
  padding:.45rem .85rem;
  border:1px solid rgba(255,255,255,.2);
  border-radius:50px;
  background:rgba(255,255,255,.12);
  -webkit-backdrop-filter:blur(14px);
  backdrop-filter:blur(14px);
  font-family:var(--font-display);
  font-size:.78rem;
  font-weight:600;
  letter-spacing:.02em;
}
.result-desc{
  max-width:80%;
  margin-top:0;
  color:rgba(255,255,255,.82);
  line-height:1.65;
}
.result-card:hover::after{
  opacity:1;
  transform:translate3d(-4%,-5%,0) scale(1.12);
}
.result-card:hover .result-icon img{
  filter:drop-shadow(0 24px 30px rgba(15,10,31,.34));
  transform:translateY(-7px) rotate(-2deg) scale(1.06);
}
.result-card:nth-child(even):hover .result-icon img{
  transform:translateY(-7px) rotate(4deg) scale(1.06);
}
@media(max-width:768px){
  .result-card{
    min-height:310px;
    padding:2rem;
  }
  .result-icon{
    top:.8rem;
    right:.65rem;
    width:135px;
    height:135px;
  }
  .result-category{
    top:1.85rem;
    left:2rem;
    max-width:calc(100% - 155px);
    letter-spacing:1.35px;
  }
  .result-title{max-width:88%;font-size:1.45rem}
  .result-desc{max-width:100%}
