  overflow:hidden;
}
.pricing-grid{
  max-width:1280px;
  gap:2rem;
  padding:1rem 0;
}
.pricing-card{
  display:flex;
  flex-direction:column;
  align-items:stretch;
  min-height:690px;
  padding:2.8rem 2.2rem 2.3rem;
  overflow:visible;
  border:1px solid rgba(255,255,255,.12);
  background:linear-gradient(145deg,rgba(255,255,255,.075),rgba(255,255,255,.035));
