.pricing-icon{
  width:122px;
  height:122px;
  margin:0 auto 1.35rem;
  border:1px solid rgba(255,255,255,.12);
  border-radius:34px;
  background:radial-gradient(circle at 35% 25%,rgba(255,255,255,.13),rgba(124,58,237,.14));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.12),0 18px 38px rgba(4,2,12,.22);
}
.pricing-icon img{
  width:118px;
  height:118px;
  object-fit:contain;
  filter:drop-shadow(0 12px 16px rgba(4,2,12,.28));
  transform:scale(.98);
  transition:transform .55s cubic-bezier(.4,0,.2,1),filter .55s;
}
.pricing-card.featured .pricing-icon{
  width:132px;
  height:132px;
  border-color:rgba(196,181,253,.34);
  background:radial-gradient(circle at 35% 25%,rgba(255,255,255,.18),rgba(124,58,237,.2));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.18),0 18px 44px rgba(124,58,237,.18);
}
.pricing-card.featured .pricing-icon img{
  width:128px;
  height:128px;
}
.pricing-card:hover .pricing-icon img{
  filter:drop-shadow(0 17px 20px rgba(4,2,12,.36));
  transform:translateY(-4px) rotate(-2deg) scale(1.05);
}
.pricing-card:nth-child(odd):hover .pricing-icon img{
  transform:translateY(-4px) rotate(2deg) scale(1.05);
}
.pricing-name{
  min-height:3.8rem;
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:1.55rem;
  line-height:1.25;
}
.pricing-desc,
.pricing-card.featured .pricing-desc{
  min-height:5.2rem;
  margin-bottom:1.35rem;
  color:rgba(255,255,255,.66);
  line-height:1.6;
}
.pricing-price{
  min-height:5.4rem;
  margin-bottom:.25rem;
  font-size:1.55rem;
  line-height:1.25;
  white-space:normal;
}
.pricing-price span{
  max-width:260px;
  margin:.45rem auto 0;
  font-family:var(--font-body);
  font-size:.82rem;
  line-height:1.45;
}
.pricing-features{
  flex:1;
  margin:1.4rem 0 2rem;
}
.pricing-features li,
.pricing-card.featured .pricing-features li{
  min-height:3.25rem;
  padding:.7rem 0;
  border-bottom-color:rgba(255,255,255,.09);
  color:rgba(255,255,255,.82);
  line-height:1.45;
}
.pricing-features li::before{
  border:1px solid rgba(52,211,153,.22);
  background:rgba(16,185,129,.14);
}
.pricing-btn-outline{
  background:rgba(255,255,255,.04);
}
.pricing-card.featured .pricing-btn-primary{
  border:1px solid rgba(255,255,255,.16);
  box-shadow:0 12px 34px rgba(124,58,237,.38);
}
.pricing-note{
  max-width:760px;
  margin:3rem auto 0;
  color:rgba(255,255,255,.56);
  font-size:.94rem;
  line-height:1.65;
  text-align:center;
}
@media(max-width:1200px){
  .pricing-card,
  .pricing-card.featured{
    min-height:0;
    transform:none;
  }
  .pricing-card.featured:hover{
    transform:translateY(-5px);
  }
  .pricing-name,
  .pricing-desc,
  .pricing-price{
    min-height:0;
  }
}
@media(max-width:480px){
  .pricing-card{
    padding:2.5rem 1.5rem 2rem;
  }
  .pricing-icon{width:106px;height:106px;border-radius:30px}
  .pricing-icon img{width:102px;height:102px}
  .pricing-card.featured .pricing-icon{width:114px;height:114px}
  .pricing-card.featured .pricing-icon img{width:110px;height:110px}
  .pricing-badge{font-size:.62rem}
}

/* FAQ в единой тёмной стеклянной стилистике с блоком форматов работы. */
.faq-section{
  position:relative;
  overflow:hidden;
  isolation:isolate;
  border-top:1px solid rgba(196,181,253,.1);
  background:
    radial-gradient(circle at 12% 18%,rgba(124,58,237,.2),transparent 30%),
    radial-gradient(circle at 88% 76%,rgba(91,33,182,.18),transparent 34%),
    linear-gradient(150deg,#17102d 0%,#0f0a1f 52%,#1b1234 100%);
  color:#fff;
}
.faq-section::before,
.faq-section::after{
  position:absolute;
  z-index:-1;
  border-radius:50%;
  content:'';
  pointer-events:none;
  filter:blur(2px);
}
.faq-section::before{
  top:6%;
  left:-10rem;
  width:28rem;
  height:28rem;
  border:1px solid rgba(167,139,250,.1);
  box-shadow:0 0 90px rgba(124,58,237,.08),inset 0 0 80px rgba(124,58,237,.05);
}
.faq-section::after{
  right:-8rem;
  bottom:5%;
  width:22rem;
  height:22rem;
  background:radial-gradient(circle,rgba(139,92,246,.12),transparent 68%);
}
.faq-section .section-header{
  position:relative;
  z-index:1;
  margin-bottom:3.75rem;
}
.faq-section .section-header h2{
  color:#fff;
}
.faq-section .section-header p{
  color:rgba(255,255,255,.62);
}
.faq-section .section-badge{
  border:1px solid rgba(196,181,253,.16);
  background:rgba(124,58,237,.18);
  color:var(--accent-light);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.08);
}
.faq-grid{
  position:relative;
  z-index:1;
  max-width:980px;
}
.faq-item{
  position:relative;
  margin-bottom:1.15rem;
  overflow:hidden;
  border:1px solid rgba(255,255,255,.11);
  border-radius:24px;
  background:linear-gradient(145deg,rgba(255,255,255,.072),rgba(255,255,255,.028));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.06),0 18px 48px rgba(4,2,12,.17);
  backdrop-filter:blur(18px);
  transition:border-color .55s cubic-bezier(.4,0,.2,1),background .55s cubic-bezier(.4,0,.2,1),box-shadow .55s cubic-bezier(.4,0,.2,1),transform .55s cubic-bezier(.4,0,.2,1);
}
.faq-item::before{
  position:absolute;
  inset:0;
  background:
    radial-gradient(circle at 85% 0%,rgba(167,139,250,.14),transparent 34%),
    linear-gradient(115deg,rgba(255,255,255,.045),transparent 34%);
  content:'';
  opacity:.3;
  pointer-events:none;
  transition:opacity .55s ease;
}
.faq-item:hover{
  border-color:rgba(196,181,253,.28);
  background:linear-gradient(145deg,rgba(255,255,255,.09),rgba(255,255,255,.04));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.09),0 22px 58px rgba(4,2,12,.25),0 0 26px rgba(124,58,237,.08);
  transform:translateY(-2px);
}
.faq-item.active{
  border-color:rgba(167,139,250,.58);
  background:linear-gradient(145deg,rgba(75,43,126,.42),rgba(32,20,59,.52));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.13),0 24px 64px rgba(4,2,12,.3),0 0 34px rgba(124,58,237,.2);
}
.faq-item.active::before{
  opacity:1;
}
.faq-question{
  position:relative;
  z-index:1;
  gap:1.5rem;
  padding:1.55rem 1.75rem;
}
.faq-question h3{
  color:#fff;
  font-size:1.08rem;
  line-height:1.45;
  text-align:left;
}
.faq-toggle{
  width:46px;
  height:46px;
  border:1px solid rgba(196,181,253,.2);
  background:rgba(124,58,237,.14);
  color:var(--accent-light);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.08);
  font-family:var(--font-display);
  font-weight:400;
  transition:transform .5s cubic-bezier(.4,0,.2,1),background .5s,border-color .5s,box-shadow .5s,color .5s;
}
.faq-item:hover .faq-toggle{
  border-color:rgba(196,181,253,.38);
  background:rgba(124,58,237,.22);
}
.faq-item.active .faq-toggle{
  border-color:rgba(255,255,255,.32);
  background:linear-gradient(135deg,#7c3aed,#8b5cf6);
  color:#fff;
  box-shadow:0 10px 30px rgba(124,58,237,.34),inset 0 1px 0 rgba(255,255,255,.22);
  transform:rotate(45deg);
}
.faq-answer{
  position:relative;
  z-index:1;
  transition:max-height .55s cubic-bezier(.4,0,.2,1);
}
.faq-item.active .faq-answer{
  max-height:420px;
}
.faq-answer p{
  position:relative;
  padding:0 5.5rem 1.65rem 1.75rem;
  color:rgba(255,255,255,.66);
  line-height:1.75;
}
.faq-answer p::before{
  display:inline-block;
  width:20px;
  height:2px;
  margin:0 .65rem .28rem 0;
  border-radius:2px;
  background:linear-gradient(90deg,var(--accent),rgba(167,139,250,.15));
  content:'';
}
@media(max-width:768px){
  .faq-section .section-header{
    margin-bottom:2.75rem;
  }
  .faq-item{
    border-radius:20px;
  }
  .faq-question{
    gap:1rem;
    padding:1.25rem 1.2rem;
  }
  .faq-question h3{
    font-size:1rem;
  }
  .faq-toggle{
    width:40px;
    height:40px;
    font-size:1.3rem;
  }
  .faq-answer p{
    padding:0 1.2rem 1.35rem;
    font-size:.94rem;
  }
}

/* Единый финальный блок связи вместо двух повторяющихся секций. */
.contact-section.contact-final{
  position:relative;
  overflow:hidden;
  isolation:isolate;
  padding:7.5rem 5%;
  border-top:1px solid rgba(196,181,253,.1);
  background:
    radial-gradient(circle at 78% 22%,rgba(124,58,237,.2),transparent 30%),
    radial-gradient(circle at 14% 88%,rgba(91,33,182,.15),transparent 32%),
    linear-gradient(150deg,#110b23 0%,#18102e 48%,#0f0a1f 100%);
}
.contact-final::before,
.contact-final::after{
  position:absolute;
  z-index:-1;
  border-radius:50%;
  content:'';
  pointer-events:none;
}
.contact-final::before{
  top:-13rem;
  right:-8rem;
  width:35rem;
  height:35rem;
  border:1px solid rgba(167,139,250,.09);
  box-shadow:0 0 110px rgba(124,58,237,.08),inset 0 0 100px rgba(124,58,237,.04);
}
.contact-final::after{
  bottom:-12rem;
  left:-9rem;
  width:30rem;
  height:30rem;
  background:radial-gradient(circle,rgba(124,58,237,.1),transparent 68%);
}
.contact-panel{
  position:relative;
  max-width:1280px;
  margin:0 auto;
  padding:4.5rem;
  display:grid;
  grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);
  gap:5rem;
  align-items:center;
  overflow:hidden;
  border:1px solid rgba(255,255,255,.13);
  border-radius:40px;
  background:linear-gradient(145deg,rgba(255,255,255,.075),rgba(255,255,255,.025));
  -webkit-backdrop-filter:blur(24px) saturate(130%);
  backdrop-filter:blur(24px) saturate(130%);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.09),0 34px 90px rgba(4,2,12,.32),0 0 44px rgba(124,58,237,.09);
}
.contact-panel::before{
  position:absolute;
  top:-55%;
  right:-12%;
  width:62%;
  height:150%;
  border-radius:50%;
  background:radial-gradient(circle,rgba(139,92,246,.13),transparent 65%);
  content:'';
  pointer-events:none;
}
.contact-copy,
.contact-actions{
  position:relative;
  z-index:1;
}
.contact-copy .section-badge{
  margin-bottom:1.4rem;
  border:1px solid rgba(196,181,253,.18);
  background:rgba(124,58,237,.18);
  color:var(--accent-light);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.08);
}
.contact-copy h2{
  max-width:560px;
  margin-bottom:1.5rem;
  color:#fff;
  font-family:var(--font-display);
  font-size:3.35rem;
  font-weight:800;
  letter-spacing:-1px;
  line-height:1.12;
}
.contact-lead{
  max-width:560px;
  margin-bottom:2rem;
  color:rgba(255,255,255,.66);
  font-size:1.08rem;
  line-height:1.75;
}
.contact-note{
  max-width:560px;
  display:flex;
  align-items:flex-start;
  gap:.75rem;
  color:rgba(255,255,255,.48);
  font-size:.88rem;
  line-height:1.6;
}
.contact-note-dot{
  width:9px;
  height:9px;
  margin-top:.36rem;
  flex:0 0 auto;
  border-radius:50%;
  background:#10b981;
  box-shadow:0 0 0 5px rgba(16,185,129,.09),0 0 18px rgba(16,185,129,.32);
}
.contact-actions{
  display:grid;
  gap:1rem;
}
.contact-messengers{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:1rem;
}
.contact-action{
  width:100%;
  min-width:0;
  min-height:100px;
  padding:1.25rem 1.35rem;
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto;
  gap:1rem;
  align-items:center;
  border:1px solid rgba(255,255,255,.12);
  border-radius:24px;
  background:linear-gradient(145deg,rgba(255,255,255,.07),rgba(255,255,255,.025));
  color:#fff;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.07),0 16px 36px rgba(4,2,12,.16);
  font-family:var(--font-display);
  text-align:left;
  text-decoration:none;
  cursor:pointer;
  appearance:none;
  transition:transform .45s cubic-bezier(.4,0,.2,1),border-color .45s,background .45s,box-shadow .45s;
}
.contact-action:hover{
  border-color:rgba(196,181,253,.3);
  background:linear-gradient(145deg,rgba(255,255,255,.1),rgba(255,255,255,.04));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.11),0 24px 52px rgba(4,2,12,.26),0 0 28px rgba(124,58,237,.1);
  transform:translateY(-4px);
}
.contact-action:focus-visible{
  outline:2px solid var(--accent-light);
  outline-offset:4px;
}
.contact-action-chat{
  min-height:116px;
  border-color:rgba(196,181,253,.34);
  background:
    radial-gradient(circle at 82% 15%,rgba(255,255,255,.13),transparent 32%),
    linear-gradient(135deg,rgba(91,33,182,.96),rgba(124,58,237,.94) 55%,rgba(139,92,246,.9));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.18),0 22px 55px rgba(76,29,149,.34),0 0 32px rgba(124,58,237,.18);
}
.contact-action-chat:hover{
  border-color:rgba(255,255,255,.42);
  background:
    radial-gradient(circle at 82% 15%,rgba(255,255,255,.19),transparent 34%),
    linear-gradient(135deg,#5b21b6,#7c3aed 55%,#8b5cf6);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.23),0 28px 68px rgba(76,29,149,.42),0 0 44px rgba(139,92,246,.24);
}
.contact-action-icon{
  width:58px;
  height:58px;
  display:flex;
  align-items:center;
  justify-content:center;
  flex:0 0 auto;
  border:1px solid rgba(255,255,255,.18);
  border-radius:18px;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.18),0 12px 24px rgba(4,2,12,.2);
}
.contact-action-icon img{
  width:30px;
  height:30px;
  display:block;
}
.contact-action-icon-chat{
  width:66px;
  height:66px;
  border-radius:20px;
  background:rgba(255,255,255,.14);
}
.contact-action-icon-chat img{
  width:36px;
  height:36px;
}
.contact-action-icon-tg{
  background:linear-gradient(135deg,#168acd,#2aabee);
}
.contact-action-icon-vk{
  background:linear-gradient(135deg,#1668c7,#2787f5);
}
.contact-action-content{
  min-width:0;
  display:flex;
  flex-direction:column;
  gap:.2rem;
}
.contact-action-content strong{
  color:#fff;
  font-size:1.04rem;
  font-weight:700;
  line-height:1.35;
}
.contact-action-chat .contact-action-content strong{
  font-size:1.22rem;
}
.contact-action-content small{
  color:rgba(255,255,255,.56);
  font-family:var(--font-body);
  font-size:.78rem;
  line-height:1.4;
}
.contact-action-chat .contact-action-content small{
  color:rgba(255,255,255,.72);
}
.contact-action-arrow{
  width:38px;
  height:38px;
  display:flex;
  align-items:center;
  justify-content:center;
  border:1px solid rgba(255,255,255,.13);
  border-radius:50%;
  background:rgba(255,255,255,.06);
  color:rgba(255,255,255,.78);
  font-family:var(--font-display);
  font-size:1.2rem;
  transition:transform .45s,background .45s,color .45s;
}
.contact-action:hover .contact-action-arrow{
  background:rgba(255,255,255,.13);
  color:#fff;
  transform:translateX(3px);
}
@media(max-width:1100px){
  .contact-panel{
    gap:3rem;
    padding:3.5rem;
  }
  .contact-copy h2{
    font-size:2.8rem;
  }
  .contact-messengers{
    grid-template-columns:1fr;
  }
}
@media(max-width:850px){
  .contact-section.contact-final{
    padding:5rem 5%;
  }
  .contact-panel{
    grid-template-columns:1fr;
    gap:3rem;
    text-align:center;
  }
  .contact-copy h2,
  .contact-lead,
  .contact-note{
    margin-left:auto;
    margin-right:auto;
  }
  .contact-note{
    justify-content:center;
    text-align:left;
  }
  .contact-messengers{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
}
@media(max-width:620px){
  .contact-section.contact-final{
    padding:4rem 5%;
  }
  .contact-panel{
    gap:2.5rem;
    padding:2rem 1.25rem;
    border-radius:28px;
  }
  .contact-copy h2{
    font-size:2rem;
    letter-spacing:-.5px;
  }
  .contact-lead{
    font-size:.96rem;
  }
  .contact-note{
    font-size:.8rem;
  }
  .contact-messengers{
    grid-template-columns:1fr;
  }
  .contact-action,
  .contact-action-chat{
    min-height:92px;
    padding:1rem;
    gap:.8rem;
    border-radius:20px;
  }
  .contact-action-icon,
  .contact-action-icon-chat{
    width:52px;
    height:52px;
    border-radius:16px;
  }
  .contact-action-icon img,
  .contact-action-icon-chat img{
    width:28px;
    height:28px;
  }
  .contact-action-content strong,
  .contact-action-chat .contact-action-content strong{
    font-size:1rem;
  }
  .contact-action-arrow{
    width:34px;
    height:34px;
  }
}

/* Спокойный стеклянный подвал в общей стилистике сайта. */
footer{
  position:relative;
  overflow:hidden;
  padding:4.5rem 5% 2.25rem;
  border-top:1px solid rgba(196,181,253,.08);
  background:
    radial-gradient(circle at 50% 0%,rgba(124,58,237,.1),transparent 34%),
    linear-gradient(180deg,#0b0716 0%,#080510 100%);
}
footer::before{
  position:absolute;
  top:-1px;
  left:12%;
  right:12%;
  height:1px;
  background:linear-gradient(90deg,transparent,rgba(167,139,250,.36),transparent);
  content:'';
  pointer-events:none;
}
.footer-content{
  max-width:1400px;
  padding:3.25rem 3.5rem 1.75rem;
  overflow:hidden;
  border:1px solid rgba(255,255,255,.09);
  border-radius:32px;
  background:linear-gradient(145deg,rgba(255,255,255,.045),rgba(255,255,255,.015));
  -webkit-backdrop-filter:blur(20px);
  backdrop-filter:blur(20px);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.055),0 28px 70px rgba(0,0,0,.2);
}
.footer-top{
  display:grid;
  grid-template-columns:minmax(260px,1.05fr) minmax(0,2fr);
  gap:5rem;
  align-items:start;
  padding-bottom:3rem;
  margin-bottom:1.75rem;
  border-bottom:1px solid rgba(255,255,255,.08);
}
.footer-brand{
  max-width:390px;
}
.footer-logo{
  margin-bottom:1.1rem;
  font-size:2.15rem;
  letter-spacing:2.5px;
}
.footer-brand p{
  color:rgba(255,255,255,.58);
  font-size:.96rem;
  line-height:1.75;
}
.footer-social{
  gap:.75rem;
  margin-top:1.6rem;
}
.footer-social a{
  width:48px;
  height:48px;
  border:1px solid rgba(255,255,255,.11);
  border-radius:15px;
  background:rgba(255,255,255,.045);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.07),0 12px 26px rgba(0,0,0,.16);
  transition:transform .4s cubic-bezier(.4,0,.2,1),border-color .4s,background .4s,box-shadow .4s;
}
.footer-social a img{
  width:23px;
  height:23px;
  display:block;
  opacity:.8;
  transition:opacity .4s,transform .4s;
}
.footer-social a:hover{
  border-color:rgba(255,255,255,.2);
  transform:translateY(-4px);
}
.footer-social-tg:hover{
  background:linear-gradient(135deg,#168acd,#2aabee);
  box-shadow:0 14px 30px rgba(42,171,238,.18);
}
.footer-social-vk:hover{
  background:linear-gradient(135deg,#1668c7,#2787f5);
  box-shadow:0 14px 30px rgba(39,135,245,.18);
}
.footer-social a:hover img{
  opacity:1;
  transform:scale(1.08);
}
.footer-links{
  display:grid;
  grid-template-columns:1.15fr .9fr 1fr;
  gap:3rem;
}
.footer-column h4{
  margin-bottom:1.25rem;
  color:rgba(255,255,255,.9);
  font-size:.98rem;
}
.footer-column ul li{
  margin-bottom:.62rem;
}
.footer-column ul a{
  display:inline-block;
  color:rgba(255,255,255,.5);
  font-size:.88rem;
  line-height:1.55;
  transition:color .3s,transform .3s;
}
.footer-column ul a:hover{
  color:var(--accent-light);
  transform:translateX(3px);
}
.footer-bottom{
  display:flex;
  justify-content:center;
  color:rgba(255,255,255,.34);
  font-size:.82rem;
  text-align:center;
}
@media(max-width:1050px){
  .footer-top{
    grid-template-columns:1fr;
    gap:3.25rem;
  }
  .footer-brand{
    max-width:520px;
  }
}
@media(max-width:720px){
  footer{
    padding:3.5rem 5% 1.5rem;
  }
  .footer-content{
    padding:2.5rem 1.5rem 1.5rem;
    border-radius:26px;
  }
  .footer-top{
    gap:2.75rem;
    padding-bottom:2.5rem;
  }
  .footer-links{
    grid-template-columns:1fr;
    gap:2.25rem;
  }
  .footer-column h4{
    margin-bottom:1rem;
  }
  .footer-column ul li{
    margin-bottom:.55rem;
  }
}

/* Профессиональные объемные иконки в карточках первого экрана. */
.floating-card{
  transition:box-shadow .4s ease;
}
.floating-card-icon{
  width:62px;
  height:62px;
  flex:0 0 62px;
  overflow:visible;
  border:1px solid rgba(124,58,237,.12);
  border-radius:19px;
  background:radial-gradient(circle at 34% 24%,#fff 0%,#f8f5ff 58%,#eee7ff 100%);
  box-shadow:inset 0 1px 0 #fff,0 10px 24px rgba(76,29,149,.13);
}
.floating-card-icon img{
  display:block;
  width:61px;
  height:61px;
  object-fit:contain;
  filter:drop-shadow(0 7px 8px rgba(76,29,149,.18));
  transform:translateY(-1px) scale(.98);
  transition:transform .45s cubic-bezier(.2,.8,.2,1),filter .45s ease;
}
.floating-card:hover{
  box-shadow:0 24px 50px rgba(40,21,87,.2),0 0 32px rgba(124,58,237,.12);
}
.floating-card:hover .floating-card-icon img{
  filter:drop-shadow(0 10px 12px rgba(76,29,149,.25));
  transform:translateY(-4px) rotate(-3deg) scale(1.06);
}
.floating-card.card-2:hover .floating-card-icon img{
  transform:translateY(-4px) rotate(3deg) scale(1.06);
}

/* Ссылки на отдельные страницы услуг для людей и поисковой навигации. */
.service-links{
  position:relative;
  z-index:3;
  margin-top:1.35rem;
  display:flex;
  flex-wrap:wrap;
  gap:.55rem;
}
.service-links a{
  padding:.48rem .78rem;
  border:1px solid rgba(124,58,237,.18);
  border-radius:999px;
  color:var(--primary-dark);
  background:rgba(124,58,237,.075);
  font-size:.76rem;
  font-weight:700;
  line-height:1.35;
  text-decoration:none;
  transition:transform .3s,border-color .3s,background .3s,color .3s,box-shadow .3s;
}
.service-links a:hover,
.service-links a:focus-visible{
  border-color:rgba(124,58,237,.36);
  color:#fff;
  background:var(--gradient-1);
  box-shadow:0 8px 20px rgba(124,58,237,.18);
  transform:translateY(-2px);
}
.contact-geo{
  max-width:720px;
  margin:1.15rem 0 0;
  color:rgba(255,255,255,.52);
  font-size:.91rem;
  line-height:1.65;
}
@media(max-width:768px){
  .service-links{justify-content:center}
  .service-card.large .service-links{justify-content:flex-start}
}

