    },
  };

  document.querySelectorAll("[data-chat-open]").forEach((button) => {
    button.addEventListener("click", () => {
      setChat(true);
      const format = pricingFormats[button.getAttribute("data-chat-format")];
      if (!format) return;

      chatState.preselectedFormat = format.workFormat;
